"""Readable, outcome-complete addendum; no changes to the draft manuscript."""
from common005 import *

def pct(x):return f'{100*x:.1f}%'
def ci(x,adjusted=False):
    if x is None:return 'Unresolvable'
    lo,hi=x['adjusted_ci' if adjusted else 'ci95'];return f"{x['mean']:.3f} [{lo:.3f}, {hi:.3f}]"
def yes(x):return 'Pass' if x else 'Fail'
def main():
    status=read(HERE/'results/status.json');audit=read(HERE/'results/verification.json');assert status['status']=='completed' and audit['status']=='passed'
    design=read(HERE/'data/design.json');screen=read(HERE/'results/screen.json');technical=read(HERE/'results/technical.json');sel=read(HERE/'data/selection.json') if (HERE/'data/selection.json').exists() else None
    summary=read(HERE/'results/analysis/summary.json') if status['test_measured'] else None
    text=['# Fresh replication with independent clean qualification\n','9 September 2026. Bridge 005. Experimental addendum to draft manuscript v2; the manuscript being reviewed is unchanged.\n']
    if summary:
        text+=[f"**Outcome: {'the qualified replication supports the central result' if summary['full_conjunction_supported'] else 'the full prespecified result is not supported'}.** The final test was completed on 1,152 configurations after the selected pair passed separate clean qualification. All planned test conditions were retained.\n",f"The selected pair is F{summary['families'][0]}/F{summary['families'][1]}. Clean test top-1 is {pct(summary['clean_top1'])}; wording transfer changes corrupted top-1 from {pct(summary['corrupt_top1'])} to {pct(summary['conditions']['wording']['top1'])}. Pooled logit recovery is {ci(summary['conditions']['wording']['recovery'])}, with a pointwise 95% interval.\n"]
    else:
        reason={'no_screen_pair':'no aligned candidate pair passed behavioral screening','no_selection_pair':'no candidate pair met all frozen selection requirements','independent_qualification_failed':'the chosen pair failed independent clean qualification'}[status['outcome']]
        text+=[f'**Outcome: the bounded qualification experiment stopped because {reason}.** The prespecified stopping rule was followed. The final held-out transfer experiment was not run, and no new final-test recovery or proximity result is claimed.\n']
    text+=['## Why this study was run\n','Bridge 004 preserved strong behavioral recovery but failed its full qualification in both new models. Medium’s lowest clean zero-reference classification was 69.8%; TinyLlama’s was 77.1%. This follow-up prioritizes an independent qualified comparison in Medium rather than adding another model. It is informed by those failures and is not an independent origin of the hypothesis.\n','## What the experiment does\n','The model completes short stories containing two people and an object. The expected answer names the person to whom the object is given or shown. Two wording families must both support reliable answers and distinguishable patterns of response to later-head ablations. A corruption replaces the repeated subject name with an unrelated third name. The transfer edit adds the donor wording’s clean-minus-corrupted signal from twelve fixed attention heads to the corrupted recipient.\n','The experiment then asks two separate questions: does that edit restore the correct answer, and is the resulting pattern of later-head ablation effects closer to the clean recipient or the clean donor? These measurements describe a specified intervention and distance metric. They do not identify every component of a circuit.\n']
    if sel and sel['families']:
        text+=['The selected wording skeletons are:\n']+[f"- **F{f}:** {design['families'][f]}" for f in sel['families']]
        text+=['\nThe final blank receives the answer name; `{s}` is one of the two earlier names. Since this pair differs from the earlier F1/F2 pair, this is a conceptual replication of the phenomenon.\n']
    text+=['## What was fixed before inference\n','The complete candidate set, tokenization-only names, contexts, selection rules, model and source heads, numerical tolerance, measurements, control distributions, inference family and stopping rules were locally frozen before new GPU inference. This is a local timing record, not public preregistration. Read [the protocol](docs/PROTOCOL.md).\n','The study uses 108 fresh names in six disjoint banks. Earlier named actors/corruptions and exact complete prompt strings were checked. Location/object pairs are new relative to Bridges 003–004 and disjoint across splits; some individual words and eight grammar skeletons recur. Two additional fixed grammar candidates were included. No name or prompt was filtered using model answers.\n','| Stage | Names | Context blocks | Configurations per family | Role |','| --- | --- | --- | --- | --- |']
    roles={'calibration':'Numerical checks only','screen':'Clean behavioral eligibility','fit':'Fit mean references, scales and centroids','selection':'Choose one pair on fresh clean data','qualification':'Independent clean gate for chosen pair','test':'One final transfer test, only if qualified'}
    for stage in ['calibration','screen','fit','selection','qualification','test']:
        names=design['names'][stage]
        blocks=len(design['blocks'][stage]);text.append(f"| {stage} | {len(names)} | {blocks} | {blocks*(len(names)//3)*4} | {roles[stage]} |")
    text+=['\nMean-ablation references, coordinate scales and centroids use fit data only. Selection requires 90% classification in every family/order/reference cell; independent qualification and test retain the original 80% requirement. Every clean behavior gate requires 95% pairwise and 85% full-vocabulary top-1 accuracy in each order. Selection never uses a scientific upstream-transfer outcome.\n','## Screening\n',f"Eligible families: {', '.join('F'+str(i) for i in screen['eligible']) or 'none'}. Aligned eligible pairs: {len(screen['pairs'])}. All ten candidates were evaluated; no additional candidates were introduced.\n",'| Family | Order 0 pairwise / top-1 | Order 1 pairwise / top-1 | Behavioral eligibility |','| --- | --- | --- | --- |']
    for family,cells in screen['cells'].items():text.append(f"| F{family} | {pct(cells['0']['pairwise'])} / {pct(cells['0']['top1'])} | {pct(cells['1']['pairwise'])} / {pct(cells['1']['top1'])} | {yes(int(family) in screen['eligible'])} |")
    if sel:
        text+=['\n## Pair selection\n','A separate selection bank evaluated references fitted on the fit bank. The table retains all behaviorally screened, token-aligned pairs. Eligibility requires both fit/selection behavior gates, 80% in-fit separation and 90% selection separation in every cell. Ties use mean selection classification, then family identifiers.\n','| Pair | Worst in-fit class | Worst selection class | Fit / selection behavior | All selection requirements |','| --- | --- | --- | --- | --- |']
        for key,s in sorted(sel['scores'].items(),key=lambda kv:(-kv[1]['worst'],-kv[1]['average'],kv[1]['families'])):
            label='/'.join('F'+str(i) for i in s['families'])+(' **selected**' if sel['families']==s['families'] else '')
            text.append(f"| {label} | {pct(min_separation(s['fit_separation']))} | {pct(s['worst'])} | {yes(behavior_pass(s['fit_behavior']))} / {yes(behavior_pass(s['selection_behavior']))} | {yes(s['eligible'])} |")
        if (HERE/'results/qualification-summary.json').exists():
            q=read(HERE/'results/qualification-summary.json');text+=['\n## Independent clean qualification\n',f"Qualification: **{yes(q['qualified'])}**. This bank was not used to choose the pair or refit any reference. It contains {q['n']} configurations.\n",'| Recipient family / order | Pairwise / top-1 | Zero / mean classification |','| --- | --- | --- |']
            for w,f in enumerate(sel['families']):
                for o in range(2):
                    b=q['behavior'][str(f)][str(o)];sep=q['separation'][f'w{w}_o{o}'];text.append(f"| F{f} / {o} | {pct(b['pairwise'])} / {pct(b['top1'])} | {' / '.join(pct(x) for x in sep)} |")
    if summary:
        s=summary;text+=['\n## Final held-out outcomes\n','The final test crosses 12 context blocks and 12 name triples with two roles, orders and wordings. The 1,152 configurations share those units. All four recovery and eight paired-distance comparisons form one 12-quantity Bonferroni family, using 50,000 crossed-bootstrap draws. Negative distance margins favor the clean recipient.\n',f"Final behavior qualification: **{yes(s['test_behavior_pass'])}**. Final dependency separation: **{yes(s['test_separation_pass'])}**. Unresolvable paired endpoints: **{s['conditions']['wording']['unresolvable_pairs']}**.\n",'| Recipient family / order | Clean pairwise / top-1 | Zero / mean classification | Adjusted recovery |','| --- | --- | --- | --- |']
        for w,f in enumerate(s['families']):
            for o in range(2):
                cell=f'w{w}_o{o}';b=s['clean_behavior'][str(f)][str(o)];text.append(f"| F{f} / {o} | {pct(b['pairwise'])} / {pct(b['top1'])} | {' / '.join(pct(v) for v in s['clean_separation'][cell])} | {ci(s['primary']['recovery'][cell],True)} |")
        text+=['\n| Recipient family / order | Adjusted zero margin | Adjusted mean margin |','| --- | --- | --- |']
        for w,f in enumerate(s['families']):
            for o in range(2):
                cell=f'w{w}_o{o}';text.append(f"| F{f} / {o} | {ci(s['primary']['margin']['zero'][cell],True)} | {ci(s['primary']['margin']['fit_mean'][cell],True)} |")
        neg=sum(v is not None and v['adjusted_ci'][1]<0 for cells in s['primary']['margin'].values() for v in cells.values());pos=sum(v is not None and v['adjusted_ci'][0]>0 for cells in s['primary']['margin'].values() for v in cells.values())
        text += [f"\nAdjusted distance intervals: {neg}/8 recipient-favoring, {pos}/8 donor-favoring, {8-neg-pos}/8 inconclusive or unresolved. All adjusted recoveries positive: {s['all_primary_recoveries_positive']}. Full conjunction supported: {s['full_conjunction_supported']}.\n",'## Controls and sensitivities\n','All intervals in this section are secondary pointwise 95%, not additional primary confirmations. Both random families were declared before inference; projected vectors stay inside the source-head output span but are not matched to natural activations.\n','| Condition | Recovery in logits | Top-1 |','| --- | --- | --- |']
        for name,v in s['conditions'].items():text.append(f"| {name} | {ci(v['recovery'])} | {pct(v['top1'])} |")
        text += [f"\nWording minus the average residual random control: {ci(s['wording_over_residual'])} logits. Wording minus the average projected random control: {ci(s['wording_over_projected'])} logits.\n",'| Distance sensitivity | Recipient-favoring | Donor-favoring | Inconclusive / unresolved |','| --- | --- | --- | --- |']
        for name,cells in s['sensitivities'].items():
            vs=[v for b in cells.values() for v in b.values()];n=sum(v is not None and v['ci95'][1]<0 for v in vs);p=sum(v is not None and v['ci95'][0]>0 for v in vs);text.append(f'| {name} | {n} | {p} | {8-n-p} |')
        text+=['\nThese counts use pointwise intervals and must not be compared with the primary counts as though their adjustment were identical. Full per-cell intervals remain in the saved summary. Each conclusion concerns a cell mean, not every individual example. Any change in direction limits a metric-independent interpretation.\n','| Reference | Change in donor distance | Change in recipient distance |','| --- | --- | --- |']
        for b,v in s['baseline_movement'].items():text.append(f"| {b} | {ci(v['q_donor'])} | {ci(v['q_recipient'])} |")
        text+=['\nChanges are measured from the corrupted starting state. An edit can move closer to both clean endpoints. Relative recipient proximity therefore does not mean no donor influence, actual recipient matching, or preservation of an entire mechanism.\n']
    if summary:text+=['View the [primary comparison figure](figures/primary-outcomes.png) and [all-pair selection figure](figures/selection-qualification.png).\n']
    text+=['## Verification and scope\n',f"Numerical validation maximum discrepancy: {technical['checks']['max_error']:.8f}, below the unchanged 0.0005 tolerance. The structural checks cover all {len(read(HERE/'data/candidates.json')):,} candidate configurations. Saved-output and preservation verification passed; all {audit['prior_files_unchanged']} previous release files and both draft-v2 document hashes remain unchanged.\n"]
    if (HERE/'results/selected-pair-replay.json').exists():
        r=read(HERE/'results/selected-pair-replay.json');text.append(f"The actual selected-pair full-boundary replay covers both directions on {r['n']} calibration configurations, with a {r['bank_n']}-configuration mean bank. Both references have nonzero target effects. Maximum behavior/signature discrepancies: {r['behavior_error']:.8f} / {r['signature_error']:.8f}. This is a complete-state technical control, not evidence that the compact edit transfers a circuit.\n")
    if summary:
        r=read(HERE/'results/computational-replay.json');text.append(f"A newly loaded engine repeats corrupted and wording behavior on all {r['n']} test configurations. A fixed {r['singleton_n']}-example subset also repeats every measured head with singleton ablation execution. Maximum errors: {r['errors']}. All pass the fixed tolerance. Saved-array analyses also reproduce exactly. These are computational checks, not new statistical replications.\n")
    text+=['The study conditions on one selected pair, one historical source set and one fitted reference. It does not estimate selection-pipeline variance, generalize to arbitrary language, or establish complete circuit identity. The new 12-quantity primary family belongs to this one-model study; Bridge 004’s 24-quantity family is unchanged. An unsuccessful stop or test remains part of the evidence.\n','## Implication for the manuscript\n']
    if summary and summary['full_conjunction_supported']:
        text.append('This supplies a new independently qualified replication: donor signals substantially improve answers while the measured dependency pattern remains closer, on average, to the clean recipient in every primary cell. All three prespecified alternative distance measures agree in this comparison, using secondary pointwise intervals. These results strengthen the specific empirical claim. The earlier failures and metric reversals remain part of the evidence, and complete circuit identity is not established. Whether the combined empirical lesson merits TMLR submission remains a scientific judgment for review.\n')
    elif summary:
        text.append('The fresh test does not meet the full central criterion. Its separate qualification, behavior, proximity and sensitivity outcomes show which part failed. The current manuscript should retain its bounded framing; this result should not be presented as a successful full replication.\n')
    else:
        text.append('This attempt did not obtain an independently qualified final comparison under its fixed search and gates. It supplies evidence about the difficulty of qualification, while leaving the new final transfer effect unmeasured. It does not repair the central replication gap or justify broader claims. The current manuscript remains suitable for work-in-progress feedback, with this stopped attempt available as an addendum.\n')
    text+=['The manuscript prepared for feedback has not been edited. Further experiments, if desired after feedback, require a separately justified design; this study must not be continued by relaxing its gates or replacing a failed selection.\n']
    content='\n'.join(text);(HERE/'RESULTS.md').write_text(content)
    intro=(f"The new final test {'supports' if summary['full_conjunction_supported'] else 'does not support'} the full frozen conjunction on the selected F{summary['families'][0]}/F{summary['families'][1]} comparison." if summary else f"The fixed qualification attempt stopped: {reason}. The final transfer test was not run.")
    handoff='\n'.join(['# Bridge 005 follow-up · 9 September 2026\n',intro+'\n','Read the [new results addendum](studies/bridge-005/RESULTS.md), including every qualification gate, adjusted primary interval, control and metric sensitivity. The [protocol](studies/bridge-005/docs/PROTOCOL.md) records what was fixed before inference.\n','The feedback draft is unchanged: [PDF](paper/draft-v2/manuscript.pdf) and [Word](paper/draft-v2/manuscript.docx). Bridge 005 is a separate experimental addendum, not a silent revision of that manuscript.\n','The earlier qualification failures and transfer-metric limitations remain in the research record. Even a successful new standardized comparison does not establish complete circuit transfer or settle publication suitability.\n','For computational reproduction, see the [study README](studies/bridge-005/README.md) and [verification record](studies/bridge-005/results/verification.json). The new combined v5 archive, once packaged, contains all v4 research members unchanged plus this follow-up. Checkpoints and installed environments remain separate dependencies.\n'])
    (ROOT/'FOLLOWUP-005.md').write_text(handoff)
    write(HERE/'results/report-verification.json',dict(status='passed',utc=now(),report_sha256=digest(HERE/'RESULTS.md'),analysis_sha256=digest(HERE/'results/analysis/summary.json') if summary else None,qualification_sha256=digest(HERE/'results/qualification-summary.json') if (HERE/'results/qualification-summary.json').exists() else None,status_sha256=digest(HERE/'results/status.json'),scope='Report generated directly from audited outcomes; visual plots are separate'))
    print('Wrote complete Bridge 005 report',flush=True)
if __name__=='__main__':main()
